mapper.select:
SELECT V.REQ_KEY AS reqKey ,R.cooNation AS cooNation FROM (
SELECT #{r.reqKey} AS REQ_KEY, #{r.companyCode} AS COMPANY_CODE, #{r.itemCode} AS ITEM_CODE, #{r.hsCode} AS HS_CODE, #{r.fromDate} AS FROM_DATE, #{r.toDate} AS TO_DATE
) V LEFT JOIN LATERAL (SELECT CASE WHEN COUNT(*) > 1 THEN 'TT' ELSE MAX(COO_NATION) END AS cooNation FROM (SELECT DISTINCT PL.VENDOR_CODE ,PL.ITEM_CODE ,ECD.COO_NATION FROM PO_LEDGER PL LEFT OUTER JOIN COO_DIVISION_V D ON D.DIVISION_CODE = PL.DIVISION_CODE AND D.COMPANY_CODE = PL.COMPANY_CODE INNER JOIN EXT_COO_CERTIFY_MST ECM ON ECM.COMPANY_CODE = PL.COMPANY_CODE INNER JOIN EXT_COO_CERTIFY_DTL ECD ON ECD.COO_CERTIFY_NO = ECM.COO_CERTIFY_NO AND ECD.COMPANY_CODE = ECM.COMPANY_CODE AND ECD.DIVISION_CODE = ECM.DIVISION_CODE AND ECD.VENDOR_CODE = PL.VENDOR_CODE AND ECD.FTA_CODE = 'PKRRC' AND ECD.HS_CODE = V.HS_CODE AND ECD.COO_YN = 'Y' WHERE ECM.SUBMIT_STATUS = '4' AND ECM.VENDOR_CODE = PL.VENDOR_CODE AND ECM.COMPANY_CODE = PL.COMPANY_CODE AND ((ECM.DOCUMENT_TYPE = 'F' AND ECM.DIVISION_CODE = PL.DIVISION_CODE) OR (ECM.DOCUMENT_TYPE = 'D' AND ECM.APPLY_TYPE = 'A') OR (ECM.DOCUMENT_TYPE = 'D' AND ECM.APPLY_TYPE = 'M' AND ECM.DIVISION_CODE = D.COO_RECEIPT_DIVISION_CODE)) AND ((ECM.COO_CERTIFY_TYPE = 'C' AND PL.WAREHOUSING_DATE BETWEEN ECD.APPLY_DATE AND ECD.END_DATE) OR (ECM.COO_CERTIFY_TYPE = 'N' AND PL.WAREHOUSING_NO = ECD.WAREHOUSING_NO AND PL.SEQ = ECD.WAREHOUSING_SEQ)) AND ECD.ITEM_CODE = PL.ITEM_CODE AND PL.ITEM_CODE = V.ITEM_CODE AND PL.COMPANY_CODE = V.COMPANY_CODE AND PL.WAREHOUSING_DATE BETWEEN V.FROM_DATE AND V.TO_DATE) X) R ON TRUE
